import pytest
from pydantic import ValidationError

from aim_pgx.errors import AppError
from aim_pgx.matching import match_patient
from aim_pgx.models import Evidence, EvidenceBundle, PatientCase


def changed(case, **updates):
    return PatientCase.model_validate(case.model_dump() | updates)


# Expected IDs are from the original CPIC response, not generated by the matcher.
@pytest.mark.parametrize(
    "b,a,alternatives,ids,status",
    [
        ("positive", "negative", "available", [8480090], "matched"),
        ("positive", "positive", "unavailable", [8480100], "matched"),
        ("positive", "unknown", "unknown", [8480092], "matched_with_missing"),
        ("negative", "positive", "available", [8480088], "matched"),
        ("negative", "positive", "unavailable", [8480097], "matched"),
        ("negative", "positive", "unknown", [8480088, 8480097], "needs_information"),
        ("negative", "negative", "unknown", [8480095], "matched"),
        ("negative", "negative", "unavailable", [8480096], "matched"),
        ("negative", "unknown", "unknown", [8480089], "partial"),
        ("unknown", "negative", "unknown", [8480093], "partial"),
        ("unknown", "positive", "available", [8480094], "partial"),
        ("unknown", "positive", "unavailable", [8480103], "partial"),
        ("unknown", "positive", "unknown", [8480094, 8480103], "needs_information"),
        ("unknown", "unknown", "unknown", [], "needs_information"),
    ],
)
def test_source_backed_cases(case, evidence, b, a, alternatives, ids, status):
    patient = changed(case, hla_b_1502=b, hla_a_3101=a, alternatives=alternatives)
    finding = match_patient(patient, evidence)
    assert [r.id for r in finding.recommendations] == ids
    assert finding.status == status
    assert all(r in evidence.bundle.recommendations for r in finding.recommendations)
    for result, label in [(b, "HLA-B*15:02"), (a, "HLA-A*31:01")]:
        assert any(label in item for item in finding.missing_information) == (result == "unknown")
    if alternatives == "unknown" and a == "positive" and b != "positive":
        assert finding.unresolved_conditions


def test_all_reported_combinations_have_contextual_matches(case, evidence):
    # Exhaust the input state space; source-specific outcomes above test the actual decisions.
    for b in ["positive", "negative", "unknown"]:
        for a in ["positive", "negative", "unknown"]:
            for alternatives in ["available", "unavailable", "unknown"]:
                result = match_patient(
                    changed(case, hla_b_1502=b, hla_a_3101=a, alternatives=alternatives), evidence
                )
                assert all(r.population.strip() != "CBZ use >3mos" for r in result.recommendations)


def test_no_alternatives_preserves_monitoring_and_strength(case, evidence):
    finding = match_patient(
        changed(case, hla_a_3101="positive", alternatives="unavailable"), evidence
    )
    row = finding.recommendations[0]
    assert row.classification == "Optional"
    assert "increased frequency of clinical monitoring" in row.drugrecommendation
    assert "Discontinue therapy" in row.drugrecommendation


def test_unknown_is_not_negative(case, evidence):
    partial = match_patient(changed(case, hla_a_3101="unknown"), evidence)
    assert partial.recommendations[0].lookupkey["HLA-A"] == "No Result"
    assert partial.status != "matched"


def test_missing_row_is_failure_not_reassurance(case, raw_bundle):
    raw_bundle["recommendations"] = [r for r in raw_bundle["recommendations"] if r["id"] != 8480095]
    evidence = Evidence(mode="live", bundle=EvidenceBundle.model_validate(raw_bundle))
    with pytest.raises(AppError, match="does not provide one matching"):
        match_patient(case, evidence)


@pytest.mark.parametrize(
    "updates,code",
    [
        ({"age": 17}, "unsupported_patient"),
        ({"first_time_use": False}, "unsupported_treatment_history"),
        ({"first_time_use": None}, "unsupported_treatment_history"),
        ({"medication": "metformin"}, "unsupported_medication"),
        ({"medication": "GLP-1"}, "underspecified_medication"),
    ],
)
def test_scope_rejections(case, evidence, updates, code):
    with pytest.raises(AppError) as error:
        match_patient(changed(case, **updates), evidence)
    assert error.value.code == code


@pytest.mark.parametrize(
    "updates",
    [
        {"hla_b_1502": "not tested"},
        {"age": "34"},
        {"first_time_use": "true"},
        {"ancestry": "Han Chinese"},
        {"age": True},
    ],
)
def test_invalid_patient_facts_rejected(case, updates):
    with pytest.raises(ValidationError):
        changed(case, **updates)
